@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    Set<V> setA = new HashSet<>();
    Set<V> setB = new HashSet<>();

    // Split vertices into two sets
    for (V vertex : resultMap.values()) {
        if (setA.size() < resultMap.size() / 2) {
            setA.add(vertex);
        } else {
            setB.add(vertex);
        }
    }

    // Add edges between all vertices in setA and setB
    for (V vertexA : setA) {
        for (V vertexB : setB) {
            target.addEdge(vertexA, vertexB);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    Set<V> partition1 = new HashSet<>();
    Set<V> partition2 = new HashSet<>();

    // Assuming resultMap contains vertices to be divided into two partitions
    int size = resultMap.size() / 2;
    int count = 0;
    for (V vertex : resultMap.values()) {
        if (count < size) {
            partition1.add(vertex);
        } else {
            partition2.add(vertex);
        }
        count++;
    }

    // Add edges between every vertex in partition1 and every vertex in partition2
    for (V vertex1 : partition1) {
        for (V vertex2 : partition2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

