    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    // Assuming resultMap contains vertices labeled "part1" and "part2"
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("part1")) {
            set1.add(entry.getValue());
        } else if (entry.getKey().startsWith("part2")) {
            set2.add(entry.getValue());
        }
    }

    // Add edges between all vertices in set1 and set2
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    // Assuming V represents vertices and E represents edges
    // Split the vertices into two sets for a bipartite graph
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();
    int index = 0;
    List<V> vertices = new ArrayList<>(resultMap.values());
    for (V vertex : vertices) {
        if (index % 2 == 0) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
        index++;
    }

    // Add edges between all vertices in set1 and set2
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    Set<V> part1 = new HashSet<>();
    Set<V> part2 = new HashSet<>();

    // Assuming resultMap contains vertices for both parts of the bipartite graph
    for (String key : resultMap.keySet()) {
        if (key.startsWith("A_")) { // Assuming vertices for the first part are prefixed with "A_"
            part1.add(resultMap.get(key));
        } else if (key.startsWith("B_")) { // Assuming vertices for the second part are prefixed with "B_"
            part2.add(resultMap.get(key));
        }
    }

    // Add all vertices to the target graph
    target.addAllVertices(part1);
    target.addAllVertices(part2);

    // Connect every vertex in part1 to every vertex in part2
    for (V vertex1 : part1) {
        for (V vertex2 : part2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

