public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.toByteArray(message, buffer);
    CodedOutputByteBufferNano byteOutput = CodedOutputByteBufferNano.newInstance(data);
    try {
        out.write((byte) ((data.length >>>  0) & 0xFF));
        out.write((byte) ((data.length >>>  8) & 0xFF));
        out.write((byte) ((data.length >>> 16) & 0xFF));
        out.write((byte) ((data.length >>> 24) & 0xFF));
        out.write(data);
    } finally {
        buffer.clear();
    }
    return data.length;
}

