static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    int adjustedDay = (dayOfMonth - 1) / dayStep * dayStep + 1;
    if (adjustedDay > 31) {
        adjustedDay = 31;
    }

    return year * 10000 + month * 100 + adjustedDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Calculate the number of days in the month
    int[] daysInMonth = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
        daysInMonth[1] = 29; // Leap year
    }

    int newDay = day - (day % dayStep) + 1;
    if (day % dayStep == 0) {
        newDay -= dayStep;
    }

    while (newDay > daysInMonth[month - 1]) {
        newDay -= daysInMonth[month - 1];
        month++;
        if (month > 12) {
            month = 1;
            year++;
            if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
                daysInMonth[1] = 29; // Leap year
            } else {
                daysInMonth[1] = 28; // Not a leap year
            }
        }
    }

    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Calculate the first day of the month
    int firstDay = 1;

    // Calculate the day offset within the month
    int dayOffset = day - firstDay;

    // Calculate the new day by rounding down to the nearest dayStep
    int newDay = firstDay + (dayOffset / dayStep) * dayStep;

    // Adjust newDay if it exceeds the last day of the month
    int lastDayOfMonth = getLastDayOfMonth(year, month);
    if (newDay > lastDayOfMonth) {
        newDay = lastDayOfMonth;
    }

    // Return the new time bucket
    return year * 10000L + month * 100L + newDay;
}

static int getLastDayOfMonth(int year, int month) {
    if (month == 2) { // February
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            return 29; // Leap year
        } else {
            return 28;
        }
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    } else {
        return 31;
    }
}

