        } else if ((c & 0xF800) == 0) {
            utfLen += 2;
        } else if ((c & 0xFFFFF800) == 0xD800 && i < len && str.charAt(i) >= 0xDC00 && str.charAt(i) <= 0xDFFF) {
            utfLen += 4; // surrogate pair
            i++;
        } else {
            utfLen += 3;
        }
    }

    byte[] out = new byte[utfLen];
    i = 0;
    int last = 0;
    while (i < len) {
        int c = str.charAt(i++);
        if ((c & 0xFF80) == 0) {
            out[last++] = (byte) c;
        } else if ((c & 0xF800) == 0) {
            out[last++] = (byte) (0xC0 | (c >> 6));
            out[last++] = (byte) (0x80 | (c & 0x3F));
        } else if ((c & 0xFFFFF800) == 0xD800 && i < len && str.charAt(i) >= 0xDC00 && str.charAt(i) <= 0xDFFF) {
            int c2 = str.charAt(i++);
            int codePoint = ((c & 0x3FF) << 10) + (c2 & 0x3FF) + 0x10000;
            out[last++] = (byte) (0xF0 | (codePoint >> 18));
            out[last++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            out[last++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            out[last++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            out[last++] = (byte) (0xE0 | (c >> 12));
            out[last++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            out[last++] = (byte) (0x80 | (c & 0x3F));
