private static LinkedBuffer ensureCapacity(int additionalCapacity, LinkedBuffer lb) {
    if (lb.offset + additionalCapacity > lb.buffer.length) {
        // Not enough space, allocate a new buffer and link it
        int newCapacity = Math.max(lb.buffer.length << 1, lb.buffer.length + additionalCapacity);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(lb.buffer, 0, newBuffer, 0, lb.offset);
        LinkedBuffer newLb = new LinkedBuffer(newBuffer, lb.offset);
        newLb.next = lb;
        return newLb;
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int start = lb.start;
    int offset = lb.offset;
    int limit = lb.limit;
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            ensureSpace(1, lb, session);
            lb.buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            ensureSpace(2, lb, session);
            lb.buffer[offset++] = (byte) (0xc0 | (c >> 6));
            lb.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length) {
                char c2 = str.charAt(i + 1);
                if (Character.isSurrogatePair(c, c2)) {
                    int codePoint = Character.toCodePoint(c, c2);
                    ensureSpace(4, lb, session);
                    lb.buffer[offset++] = (byte) (0xf0 | ((codePoint >> 18) & 0x07));
                    lb.buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                    lb.buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                    lb.buffer[offset++] = (byte) (0x80 | (codePoint & 0x3f));
                    i++;
                }
            } else {
                throw new IllegalArgumentException("Unpaired surrogate at index " + i);
            }
        } else {
            ensureSpace(3, lb, session);
            lb.buffer[offset++] = (byte) (0xe0 | ((c >> 12) & 0x0f));
            lb.buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            lb.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        }
    }
    lb.offset = offset;
    return lb;
}

private static void ensureSpace(int additionalBytes, LinkedBuffer lb, WriteSession session) {
    if (lb.offset + additionalBytes > lb.limit) {
        lb = session.expandCapacity(additionalBytes, lb);
    }
}

