private static String substitueVariables(String value, Properties props) {
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        int j = value.indexOf("${", i);
        if (j == -1) {
            sb.append(value.substring(i));
            break;
        }
        sb.append(value.substring(i, j));
        int k = value.indexOf('}', j + 2);
        if (k == -1) {
            sb.append(value.substring(j));
            break;
        }
        String varName = value.substring(j + 2, k);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            sb.append(varValue);
        } else {
            sb.append("${").append(varName).append("}");
        }
        i = k + 1;
    }
    return sb.toString();
}

