protected int removeUnusedNodes(){
    int removedCount = 0;
    Iterator<Category> iterator = categories.iterator();
    while (iterator.hasNext()) {
        Category category = iterator.next();
        if (!category.isActive()) {
            iterator.remove();
            removedCount++;
        } else {
            removedCount += category.removeUnusedNodes();
        }
    }
    return removedCount;
}

protected int removeUnusedNodes(){
    int count = 0;
    if (this.root != null) {
        count = removeUnusedNodesRecursive(this.root);
    }
    return count;
}

private int removeUnusedNodesRecursive(CategoryNode node) {
    int removedCount = 0;
    List<CategoryNode> toRemove = new ArrayList<>();

    for (CategoryNode child : node.getChildren()) {
        if (!child.isActive()) {
            toRemove.add(child);
            removedCount++;
        } else {
            removedCount += removeUnusedNodesRecursive(child);
        }
    }

    node.getChildren().removeAll(toRemove);
    return removedCount;
}

