        if (!category.isActive()) {
            iterator.remove();
            removedCount++;
            removedCount += removeUnusedNodesRecursively(category.getChildren());
        }
    }
    return removedCount;
}

private int removeUnusedNodesRecursively(List<Category> children) {
    int removedCount = 0;
    Iterator<Category> iterator = children.iterator();
    while (iterator.hasNext()) {
        Category child = iterator.next();
        if (!child.isActive()) {
            iterator.remove();
            removedCount++;
        }
        removedCount += removeUnusedNodesRecursively(child.getChildren());
    }
    return removedCount;
}

protected int removeUnusedNodes(){
    int removedCount = 0;
    List<Category> toRemove = new ArrayList<>();

    for (Category node : this.categories) {
        if (!node.isActive()) {
            toRemove.add(node);
        }
    }

    for (Category node : toRemove) {
        this.categories.remove(node);
        removedCount++;
    }

    return removedCount;
}

protected int removeUnusedNodes(){
    int removedNodesCount = 0;
    // Assuming 'root' is the root of the Category tree
    if (root != null) {
        removedNodesCount = removeInactiveNodes(root);
    }
    return removedNodesCount;
}

private int removeInactiveNodes(Category node) {
    int removedCount = 0;
    if (!node.isActive()) {
        // If the node is inactive, remove it from its parent
        if (node.getParent() != null) {
            node.getParent().getChildren().remove(node);
        }
        removedCount++;
    } else {
        // Otherwise, recursively check its children
        Iterator<Category> it = node.getChildren().iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove(); // Remove inactive child
                removedCount++;
            } else {
                removedCount += removeInactiveNodes(child);
            }
        }
    }
    return removedCount;
}

