protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPathImpl<V, E> path = new GraphPathImpl<>(graph, null);
    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return path;
    }
    V startVertex = graph.getEdgeSource(edges.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);
    V currentVertex = startVertex;

    for (E edge : edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (source.equals(currentVertex)) {
            vertexList.add(target);
            currentVertex = target;
        } else if (target.equals(currentVertex)) {
            vertexList.add(source);
            currentVertex = source;
        } else {
            throw new IllegalArgumentException("Provided edges do not form a valid path");
        }
    }

    path.setStartVertex(startVertex);
    path.setEndVertex(currentVertex);
    path.setEdges(vertexList, edges);

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPathImpl<V, E> path = new GraphPathImpl<>(graph, graph.getEdgeSource(tour.iterator().next()), graph.getEdgeTarget(tour.iterator().next()), 0.0);
    List<E> edgesInOrder = new ArrayList<>(tour);
    V currentVertex = graph.getEdgeSource(edgesInOrder.get(0));

    for (E edge : edgesInOrder) {
        if (graph.getEdgeSource(edge).equals(currentVertex)) {
            path.addEdge(edge);
            path.setEndVertex(graph.getEdgeTarget(edge));
            currentVertex = graph.getEdgeTarget(edge);
        } else {
            path.addEdge(edge);
            path.setEndVertex(graph.getEdgeSource(edge));
            currentVertex = graph.getEdgeSource(edge);
        }
        path.setWeight(path.getWeight() + graph.getEdgeWeight(edge));
    }

    return path;
