protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    Map<V, V> previousVertices = new HashMap<>();
    Map<E, V> edgeTargets = new HashMap<>();
    Set<V> visitedVertices = new HashSet<>();

    visitedVertices.add(startVertex);
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (visitedVertices.contains(source)) {
            previousVertices.put(target, source);
            edgeTargets.put(edge, target);
            visitedVertices.add(target);
        } else {
            previousVertices.put(source, target);
            edgeTargets.put(edge, source);
            visitedVertices.add(source);
        }
    }

    List<E> pathEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();
    V currentVertex = startVertex;
    while (true) {
        pathVertices.add(currentVertex);
        E edge = null;
        for (Map.Entry<E, V> entry : edgeTargets.entrySet()) {
            if (entry.getValue().equals(currentVertex)) {
                edge = entry.getKey();
                break;
            }
        }
        if (edge == null) {
            break;
        }
        pathEdges.add(edge);
        currentVertex = previousVertices.get(currentVertex);
        if (currentVertex == startVertex) {
            break;
        }
    }

    return new GraphPathImpl<>(graph, startVertex, pathEdges, 0.0);
}

