public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the input paths
    String normalizedPath = path.endsWith("/") ? path : path + "/";
    String normalizedRelativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split the normalized relative path by "/"
    String[] parts = normalizedRelativePath.split("/");

    // Use a stack to build the resulting path
    Stack<String> pathStack = new Stack<>();
    for (String part : normalizedPath.split("/")) {
        if (!part.isEmpty()) {
            pathStack.push(part);
        }
    }

    for (String part : parts) {
        if (part.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (part.equals(".")) {
            // Do nothing for current directory
        } else {
            pathStack.push(part);
        }
    }

    // Build the final path
    StringBuilder resultPath = new StringBuilder();
    while (!pathStack.isEmpty()) {
        resultPath.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            resultPath.insert(0, "/");
        }
    }

    return resultPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Normalize the input paths
    String normalizedPath = path.endsWith("/") ? path : path + "/";
    String normalizedRelativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Tokenize the paths
    String[] pathTokens = normalizedPath.split("/");
    String[] relativePathTokens = normalizedRelativePath.split("/");

    // Process the relative path tokens
    for (String token : relativePathTokens) {
        if (token.equals("..")) {
            if (pathTokens.length > 1) {
                // Move up one directory
                pathTokens = Arrays.copyOfRange(pathTokens, 0, pathTokens.length - 1);
            }
        } else if (!token.equals(".")) {
            // Add the directory to the path
            pathTokens = Arrays.copyOf(pathTokens, pathTokens.length + 1);
            pathTokens[pathTokens.length - 1] = token;
        }
    }

    // Join the path tokens back into a single string
    return String.join("/", pathTokens);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    // Normalize the paths by ensuring they end with a "/"
    if (!path.endsWith("/")) {
        path += "/";
