    }

    // Tokenize the relative path
    String[] parts = relativePath.split("/");

    // Process each part of the relative path
    for (String part : parts) {
        if (part.equals("..")) {
            // Move up one directory
            int lastSlash = path.lastIndexOf('/', path.length() - 2);
            if (lastSlash != -1) {
                path = path.substring(0, lastSlash + 1);
            }
        } else if (!part.equals(".")) {
            // Add the directory or file name
            path += part + "/";
        }
    }

    // Remove the trailing "/" if it's not the root
    if (path.length() > 1 && path.endsWith("/")) {
